
if (typeof window !== "undefined" && !window.__fetchIntercepted) {
  window.__fetchIntercepted = true;
  const originalFetch = window.fetch;
  window.fetch = async function(...args) {
    let urlStr = "";
    try {
      if (typeof args[0] === "string") urlStr = args[0];
      else if (args[0] instanceof URL) urlStr = args[0].href;
      else if (args[0] && typeof args[0].url === "string") urlStr = args[0].url;
    } catch(e) {}
    
    if (urlStr.includes("/api/auth/login") || urlStr.includes("/api/auth/register")) {
      return new Response(JSON.stringify({ accessToken: "mock_token" }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    
    // Also mock /api/users/me just in case it bypasses ri
    if (urlStr.includes("/api/users/me")) {
      return new Response(JSON.stringify({
        id: "1",
        email: "issahildhavale@gmail.com",
        accountType: "organization",
        isFreeUser: false,
        organizations: [{id: "org_1", name: "Mock Org", role: "owner"}]
      }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    
    return originalFetch.apply(this, args);
  };
}
